prog='''def transform(grid):
    import copy
    g = copy.deepcopy(grid)
    src = copy.deepcopy(grid)
    H, W = len(g), len(g[0])
    runs = set()
    for r in range(H):
        c = 0
        while c < W:
            if src[r][c]:
                c2 = c
                while c2 < W and src[r][c2]:
                    c2 += 1
                if c2 - c > 1:
                    runs.update((r, x) for x in range(c, c2))
                c = c2
            else:
                c += 1
    seqs = []
    for r in range(H):
        c = 0
        while c < W:
            if src[r][c]:
                c2 = c
                while c2 < W and src[r][c2]:
                    c2 += 1
                if c2 - c > 1:
                    seqs.append([src[r][x] for x in range(c, c2)])
                c = c2
            else:
                c += 1
    for r in range(H):
        for c in range(W):
            v = src[r][c]
            if v and (r, c) not in runs:
                for s in seqs:
                    if v in s:
                        st = c - s.index(v)
                        for i, sv in enumerate(s):
                            if 0 <= st + i < W:
                                g[r][st + i] = sv
                        break
    return g
'''
